  const core = window.Chili3dCore;
  const app = core.getCurrentApplication();
  const doc = app.activeView.document;
  const commandService = Array.from(app.services).find((service) => service?.constructor?.name === "CommandService");
  const originalPickShape = doc.selection.pickShape;
  const originalDisplayMesh = doc.visual.context.displayMesh;
  const originalRemoveMesh = doc.visual.context.removeMesh;
  const transform = core.Matrix4.identity();
  const start = new core.XYZ({ x: 1, y: 2, z: 3 });
  const end = new core.XYZ({ x: 4, y: 6, z: 8 });
  const transformedEdge = {
    curve: { startPoint: () => start, endPoint: () => end },
    length: () => 42.5,
    mesh: { edges: { lineWidth: 1, color: 0, position: new Float32Array([0, 0, 0, 1, 1, 1]) } },
    dispose: () => {},
  };
  const edge = { shapeType: core.ShapeTypes.edge, transformedMul: () => transformedEdge };
  const rootNode = { id: "smoke-root", name: "Smoke Root", parent: undefined };
  const node = { id: "smoke-edge-node", name: "Smoke Edge Node", parent: rootNode };
  const shapeData = {
    shape: edge,
    owner: {
      node,
      transform,
      worldTransform: () => transform,
      boundingBox: () => undefined,
      dispose: () => {},
      locked: false,
      visible: true,
    },
    transform,
    point: new core.XYZ({ x: 10, y: 20, z: 30 }),
    indexes: [11, 22],
  };
  let pickCount = 0;
  let releaseSecondPick;
  doc.visual.context.displayMesh = () => 987654;
  doc.visual.context.removeMesh = () => {};
  doc.selection.pickShape = async (_prompt, controller) => {
    pickCount += 1;
    if (pickCount === 1) {
      controller.success();
      return [shapeData];
    }
    await new Promise((resolve) => {
      releaseSecondPick = resolve;
      window.__measureSmokeRelease = resolve;
      controller.onCancelled(() => resolve());
    });
    controller.cancel();
    return [];
