            if s.GetType()==GeomAbs_Cylinder:
                cyl=s.Cylinder(); fd.update({"R":round(cyl.Radius(),6),"axis_loc":vec(cyl.Location()),"axis_dir":vec(cyl.Axis().Direction())})
            faces.append(fd)
    print({k:v for k,v in r.items() if k!="shape"}, "faces", faces)
