from pathlib import Path
from OCP.STEPCAFControl import STEPCAFControl_Reader
from OCP.TDocStd import TDocStd_Document
from OCP.TCollection import TCollection_ExtendedString
from OCP.XCAFDoc import XCAFDoc_DocumentTool
from OCP.TDF import TDF_LabelSequence
from OCP.TDataStd import TDataStd_Name
from OCP.Bnd import Bnd_Box
from OCP.BRepBndLib import BRepBndLib

path='../../hardware/follower/step/arm.step'
reader=STEPCAFControl_Reader(); reader.SetNameMode(True)
status=reader.ReadFile(path)
print('read status', status)
doc=TDocStd_Document(TCollection_ExtendedString('doc'))
print('transfer', reader.Transfer(doc))
tool=XCAFDoc_DocumentTool.ShapeTool_s(doc.Main())

def name(label):
    attr=TDataStd_Name()
    try:
        if label.FindAttribute(TDataStd_Name.GetID_s(), attr):
            return attr.Get().ToExtString()
    except Exception as e:
        return f'<nameerr {e}>'
    return ''

def bbox(shape):
    b=Bnd_Box(); BRepBndLib.Add_s(shape,b); vals=b.Get(); return tuple(round(v,3) for v in vals)

def label_id(label):
    # entry as string?
    try:
        return label.EntryDumpToString()
    except Exception:
        return str(label)

def dump(label, depth=0, loc_chain=None):
    nm=name(label)
    flags=[]
    for fname, fn in [('free',tool.IsFree_s),('asm',tool.IsAssembly_s),('comp',tool.IsComponent_s),('simple',tool.IsSimpleShape_s),('shape',tool.IsShape_s)]:
        try:
            if fn(label): flags.append(fname)
        except Exception: pass
    line='  '*depth + f'{label_id(label)} name={nm!r} flags={flags}'
    try:
        sh=tool.GetShape_s(label)
        if not sh.IsNull(): line += ' bbox='+str(bbox(sh))
    except Exception as e:
        line += f' bboxerr={e}'
    print(line[:260])
    comps=TDF_LabelSequence()
    try:
        ok=tool.GetComponents_s(label, comps, False)
    except TypeError:
        ok=tool.GetComponents_s(label, comps)
    except Exception as e:
        ok=False
    if comps.Length():
        for i in range(1, comps.Length()+1):
            dump(comps.Value(i), depth+1)

seq=TDF_LabelSequence(); tool.GetFreeShapes(seq)
print('free', seq.Length())
for i in range(1, seq.Length()+1):
    dump(seq.Value(i), 0)
PY'

